-- 审计日志。
CREATE TABLE IF NOT EXISTS audit_operation_log (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL DEFAULT 0, username TEXT NOT NULL DEFAULT '', module TEXT NOT NULL DEFAULT '', action TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '', method TEXT NOT NULL DEFAULT 'POST', path TEXT NOT NULL DEFAULT '', status INTEGER NOT NULL DEFAULT 200, error_message TEXT NOT NULL DEFAULT '', cost_time INTEGER NOT NULL DEFAULT 0, ip TEXT NOT NULL DEFAULT '', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP); -- 操作审计日志
CREATE TABLE IF NOT EXISTS audit_login_log (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL DEFAULT 0, username TEXT NOT NULL DEFAULT '', login_type TEXT NOT NULL DEFAULT 'web', status TEXT NOT NULL DEFAULT 'success', ip TEXT NOT NULL DEFAULT '', message TEXT NOT NULL DEFAULT '', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP); -- 登录审计日志
CREATE TABLE IF NOT EXISTS audit_data_log (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL DEFAULT 0, username TEXT NOT NULL DEFAULT '', table_name TEXT NOT NULL DEFAULT '', record_id INTEGER NOT NULL DEFAULT 0, action TEXT NOT NULL DEFAULT '', old_data TEXT NOT NULL DEFAULT '', new_data TEXT NOT NULL DEFAULT '', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP); -- 数据变更审计日志
